fn cmd_arg_render(a:&Argument,counter:&mut usize,prelude:&mut String)->String{if a.all_arguments{return cmd_forward_args()}a.segments.iter().map(|segment|match segment{ArgumentSegment::Literal(v)=>format!("\"{}\"",v.replace('"', "\\\"")),ArgumentSegment::EnvRef(n)=>format!("%{n}%"),ArgumentSegment::Positional(n)=>format!("%{n}"),ArgumentSegment::AllArguments=>cmd_forward_args(),ArgumentSegment::LiteralAt=>"@".into(),ArgumentSegment::CommandSubstitution(inner)=>{let variable=format!("__aliasc_sub_{counter}");*counter+=1;let command=cmd_command_render(inner,None,true,counter,prelude);prelude.push_str(&format!("set \"{variable}=\"\nfor /f \"delims=\" %%S in ('{command}') do set \"{variable}=%%S\"\n"));format!("\"%{variable}%\"")}}).collect()}
fn cmd_forward_args()->String{"%1 %2 %3 %4 %5 %6 %7 %8 %9".into()}
fn cmd_arg(a:&Argument)->String{if a.all_arguments{return cmd_forward_args()}a.segments.iter().map(|s|match s{ArgumentSegment::Literal(v)=>format!("\"{}\"",v.replace('"', "\\\"")),ArgumentSegment::EnvRef(n)=>format!("%{n}%"),ArgumentSegment::Positional(n)=>format!("%{n}"),ArgumentSegment::AllArguments=>cmd_forward_args(),ArgumentSegment::LiteralAt=>"@".into(),ArgumentSegment::CommandSubstitution(_)=>"".into()}).collect()}
